window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-35ba3e0dbe6a8eaa"]={"versions": [{"id": "FIG-35ba3e0dbe6a8eaa", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Kontrollfluss- und Entscheidungsbaum für Vorbedingungsprüfungen).</li>\n<li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic / Adaptive Platform, BSW-Modul <code>E2EXf</code> (<em>E2E Transformer</em>, SWS-Kapitel 7 / Funktionsablauf).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der internen Verifikationsroutine <code>E2EXf_input_checks_PXXm()</code> zur Prüfung obligatorischer Schnittstellenparameter für Client-Server- bzw. nachrichtenbasierte E2E-Profile mit Metadaten-/Header-Extraktion (generisches Profilschema <code>PXXm</code>, wie z. B. P04m, P07m, P08m, P44m).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Parameter & Datenobjekte:</strong></li>\n<li><code>Profile</code>: Laufzeit- oder Konfigurationsparameter zur Identifikation des aktiven E2E-Profils.</li>\n<li><code>PXXm</code>: Platzhalter-Klasse für E2E-Profile mit Metadaten-Unterstützung (SOME/IP-Header-Auswertung, Request/Response-Tracking).</li>\n<li><code>extractProtocolHeaderFields</code> <em>(im Diagramm mit Spezifikationstypo als <code>extractPrtocolHeaderFields</code> dargestellt)</em>: Funktionszeiger (Callback) zur Extraktion von Protokollfeldern (z. B. Client-ID, Session-ID, Sequence-Counter aus dem oberen Protokoll-Header).</li>\n<li><code>csTransactionHandle</code>: Zeiger/Handle auf den Client/Server-Transaktionskontext zur Korrelation von Aufruf und Rückmeldung.</li>\n<li><strong>UML-Steuerelemente:</strong></li>\n<li>Startknoten (Initial Node).</li>\n<li>Drei Entscheidungsknoten (Decision Diamonds) mit komplementären Guard-Bedingungen (<code>[TRUE]</code>, <code>[FALSE]</code>).</li>\n<li>Zwei Aktivitätsendknoten (Activity Final Nodes) mit den booleschen Rückgabewerten <code>return [FALSE]</code> und <code>return [TRUE]</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner, blockierungsfreier Kontrollfluss vor Eintritt in die eigentliche E2E-Transformationslogik (<code>Protect</code> / <code>Check</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Profil-Klassifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>Profile == PXXm</code>.</li>\n<li><code>[FALSE]</code>-Zweig: Bei Nicht-PXXm-Profilen sind keine PXXm-spezifischen Zeiger erforderlich $\\rightarrow$ unmittelbarer Übergang zu <code>return [TRUE]</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Einzugrenzen auf PXXm-Pfad $\\rightarrow$ Weiterschaltung zu Schritt 2.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung des Header-Extraktionszeigers:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>extractProtocolHeaderFields == NULL</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Ungültiger Funktionszeiger $\\rightarrow$ Abbruch via <code>return [FALSE]</code>.</li>\n<li><code>[FALSE]</code>-Zweig: Zeiger vorhanden $\\rightarrow$ Weiterschaltung zu Schritt 3.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung des Transaktions-Handles:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>csTransactionHandle == NULL</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Fehlendes Handle $\\rightarrow$ Abbruch via <code>return [FALSE]</code>.</li>\n<li><code>[FLASE]</code>-Zweig <em>(Spezifikationstypo für <code>[FALSE]</code>)</em>: Beide erforderlichen Parameter sind ungleich <code>NULL</code> $\\rightarrow$ Abschluss via <code>return [TRUE]</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Fehlerbehandlung & Safety-Vertrag (<code>SWS_E2EXf_00106</code>, <code>SWS_E2EXf_00180</code>):</strong></li>\n<li>Liefert <code>E2EXf_input_checks_PXXm()</code> den Wert <code>FALSE</code> zurück, bricht der Transformer die Ausführung deterministisch mit dem Fehlercode <code>E_SAFETY_HARD_RUNTIMEERROR</code> ab. Es erfolgt keine Datenverarbeitung oder PDU-Weiterleitung.</li>\n<li><strong>BSW- & Treiber-Implementierung:</strong></li>\n<li>Guard-Ausdrücke gegen Nullzeiger müssen zwingend vor jedem Speicher- oder Funktionszugriff ausgewertet werden, um Trap-/Kernel-Exceptions im BSW-Kontext zu verhindern.</li>\n<li>Spezifikations-Hinweis: Die typografischen Fehler im Diagramm (<code>extractPrtocolHeaderFields</code> sowie Guard <code>[FLASE]</code>) sind in C-Implementierungen anhand der normativen Signatur aus <code>[SWS_E2EXf_00180]</code> (<code>extractProtocolHeaderFields</code> und <code>FALSE</code>) aufzulösen.</li>\n<li><strong>RTE- & Codegenerator-Konfiguration:</strong></li>\n<li>Bei Konfiguration von Schnittstellen über Profile <code>P04m</code>, <code>P07m</code>, <code>P08m</code> oder <code>P44m</code> muss der BSW-/RTE-Generator sicherstellen, dass sowohl die Callback-Funktion zur Header-Extraktion als auch der Puffer für das Transaktions-Handle statisch instanziiert und dem Transformer übergeben werden.</li>\n<li><strong>Anforderungs-Traceability:</strong> Dient der Umsetzung von <code>RS_E2E_08538</code> zur Absicherung nachrichtenbasierter und Client/Server-Kommunikationsmuster gegen Schnittstellen-Fehlkonfigurationen.</li>\n</ul>"}, {"id": "FIG-f709196eb7ded3ac", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Kontrollfluss- und Entscheidungsbaum für Vorbedingungsprüfungen).</li>\n<li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic / Adaptive Platform, BSW-Modul <code>E2EXf</code> (<em>E2E Transformer</em>, SWS-Kapitel 7 / Funktionsablauf).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der internen Verifikationsroutine <code>E2EXf_input_checks_PXXm()</code> zur Prüfung obligatorischer Schnittstellenparameter für Client-Server- bzw. nachrichtenbasierte E2E-Profile mit Metadaten-/Header-Extraktion (generisches Profilschema <code>PXXm</code>, wie z. B. P04m, P07m, P08m, P44m).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Parameter & Datenobjekte:</strong></li>\n<li><code>Profile</code>: Laufzeit- oder Konfigurationsparameter zur Identifikation des aktiven E2E-Profils.</li>\n<li><code>PXXm</code>: Platzhalter-Klasse für E2E-Profile mit Metadaten-Unterstützung (SOME/IP-Header-Auswertung, Request/Response-Tracking).</li>\n<li><code>extractProtocolHeaderFields</code> <em>(im Diagramm mit Spezifikationstypo als <code>extractPrtocolHeaderFields</code> dargestellt)</em>: Funktionszeiger (Callback) zur Extraktion von Protokollfeldern (z. B. Client-ID, Session-ID, Sequence-Counter aus dem oberen Protokoll-Header).</li>\n<li><code>csTransactionHandle</code>: Zeiger/Handle auf den Client/Server-Transaktionskontext zur Korrelation von Aufruf und Rückmeldung.</li>\n<li><strong>UML-Steuerelemente:</strong></li>\n<li>Startknoten (Initial Node).</li>\n<li>Drei Entscheidungsknoten (Decision Diamonds) mit komplementären Guard-Bedingungen (<code>[TRUE]</code>, <code>[FALSE]</code>), farblich codiert gemäß Legende für allgemeingültige Pfade (<em>All types</em>).</li>\n<li>Zwei Aktivitätsendknoten (Activity Final Nodes) mit den booleschen Rückgabewerten <code>return [FALSE]</code> und <code>return [TRUE]</code>.</li>\n<li><strong>Visuelle Zusatzelemente / Legende:</strong></li>\n<li>Legendenkasten <em>Communication Types</em> zur Farbcodierung von Kommunikationsmustern: <em>All types</em> (Beige/Pfirsich), <em>Sender/Receiver</em> (Hellgrün), <em>Publisher/Subscriber</em> (Grün), <em>C/S: Server</em> (Hellblau), <em>C/S: Client</em> (Rosa), <em>Signal to Service</em> (Gelb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner, blockierungsfreier Kontrollfluss vor Eintritt in die eigentliche E2E-Transformationslogik (<code>Protect</code> / <code>Check</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Profil-Klassifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>Profile == PXXm</code>.</li>\n<li><code>[FALSE]</code>-Zweig: Bei Nicht-PXXm-Profilen sind keine PXXm-spezifischen Zeiger erforderlich $\\rightarrow$ unmittelbarer Übergang zu <code>return [TRUE]</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Einzugrenzen auf PXXm-Pfad $\\rightarrow$ Weiterschaltung zu Schritt 2.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung des Header-Extraktionszeigers:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>extractProtocolHeaderFields == NULL</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Ungültiger Funktionszeiger $\\rightarrow$ Abbruch via <code>return [FALSE]</code>.</li>\n<li><code>[FALSE]</code>-Zweig: Zeiger vorhanden $\\rightarrow$ Weiterschaltung zu Schritt 3.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung des Transaktions-Handles:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>csTransactionHandle == NULL</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Fehlendes Handle $\\rightarrow$ Abbruch via <code>return [FALSE]</code>.</li>\n<li><code>[FALSE]</code>-Zweig: Beide erforderlichen Parameter sind ungleich <code>NULL</code> $\\rightarrow$ Abschluss via <code>return [TRUE]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Fehlerbehandlung & Safety-Vertrag (<code>SWS_E2EXf_00106</code>, <code>SWS_E2EXf_00180</code>):</strong></li>\n<li>Liefert <code>E2EXf_input_checks_PXXm()</code> den Wert <code>FALSE</code> zurück, bricht der Transformer die Ausführung deterministisch mit dem Fehlercode <code>E_SAFETY_HARD_RUNTIMEERROR</code> ab. Es erfolgt keine Datenverarbeitung oder PDU-Weiterleitung.</li>\n<li><strong>BSW- & Treiber-Implementierung:</strong></li>\n<li>Guard-Ausdrücke gegen Nullzeiger müssen zwingend vor jedem Speicher- oder Funktionszugriff ausgewertet werden, um Trap-/Kernel-Exceptions im BSW-Kontext zu verhindern.</li>\n<li>Spezifikations-Hinweis: Die typografischen Fehler im Diagramm (<code>extractPrtocolHeaderFields</code> sowie Guard <code>[FLASE]</code>) sind in C-Implementierungen anhand der normativen Signatur aus <code>[SWS_E2EXf_00180]</code> (<code>extractProtocolHeaderFields</code> und <code>FALSE</code>) aufzulösen.</li>\n<li><strong>RTE- & Codegenerator-Konfiguration:</strong></li>\n<li>Bei Konfiguration von Schnittstellen über Profile <code>P04m</code>, <code>P07m</code>, <code>P08m</code> oder <code>P44m</code> muss der BSW-/RTE-Generator sicherstellen, dass sowohl die Callback-Funktion zur Header-Extraktion als auch der Puffer für das Transaktions-Handle statisch instanziiert und dem Transformer übergeben werden.</li>\n<li><strong>Anforderungs-Traceability:</strong> Dient der Umsetzung von <code>RS_E2E_08538</code> zur Absicherung nachrichtenbasierter und Client/Server-Kommunikationsmuster gegen Schnittstellen-Fehlkonfigurationen.</li>\n</ul>"}, {"id": "FIG-72d33dd2e56f39a3", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Kontrollfluss- und Entscheidungsbaum für Vorbedingungsprüfungen).</li>\n<li><strong>Architektur-Einordnung:</strong> AUTOSAR Classic / Adaptive Platform, BSW-Modul <code>E2EXf</code> (<em>E2E Transformer</em>, SWS-Kapitel 7 / Funktionsablauf).</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der internen Verifikationsroutine <code>E2EXf_input_checks_PXXm()</code> zur Prüfung obligatorischer Schnittstellenparameter für Client-Server- bzw. nachrichtenbasierte E2E-Profile mit Metadaten-/Header-Extraktion (generisches Profilschema <code>PXXm</code>, wie z. B. P04m, P07m, P08m, P44m).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Parameter & Datenobjekte:</strong></li>\n<li><code>Profile</code>: Laufzeit- oder Konfigurationsparameter zur Identifikation des aktiven E2E-Profils.</li>\n<li><code>PXXm</code>: Platzhalter-Klasse für E2E-Profile mit Metadaten-Unterstützung (SOME/IP-Header-Auswertung, Request/Response-Tracking).</li>\n<li><code>extractProtocolHeaderFields</code> <em>(im Diagramm mit Spezifikationstypo als <code>extractPrtocolHeaderFields</code> dargestellt)</em>: Funktionszeiger (Callback) zur Extraktion von Protokollfeldern (z. B. Client-ID, Session-ID, Sequence-Counter aus dem oberen Protokoll-Header).</li>\n<li><code>csTransactionHandle</code>: Zeiger/Handle auf den Client/Server-Transaktionskontext zur Korrelation von Aufruf und Rückmeldung.</li>\n<li><strong>UML-Steuerelemente:</strong></li>\n<li>Startknoten (Initial Node).</li>\n<li>Drei Entscheidungsknoten (Decision Diamonds) mit komplementären Guard-Bedingungen (<code>[TRUE]</code>, <code>[FALSE]</code>), farblich codiert gemäß Legende für allgemeingültige Pfade (<em>All types</em>).</li>\n<li>Zwei Aktivitätsendknoten (Activity Final Nodes) mit den booleschen Rückgabewerten <code>return [FALSE]</code> und <code>return [TRUE]</code>.</li>\n<li><strong>Visuelle Zusatzelemente / Legende:</strong></li>\n<li>Legendenkasten <em>Legend</em> (zuvor <em>Communication Types</em>) zur Farbcodierung von Kommunikationsmustern: <em>All types</em> (Beige/Pfirsich), <em>Sender/Receiver</em> (Hellgrün), <em>Publisher/Subscriber</em> (Grün), <em>C/S: Server</em> (Hellblau), <em>C/S: Client</em> (Rosa), <em>Signal to Service</em> (Gelb).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchroner, blockierungsfreier Kontrollfluss vor Eintritt in die eigentliche E2E-Transformationslogik (<code>Protect</code> / <code>Check</code>):</p>\n<ol class=\"fig-list\">\n<li><strong>Profil-Klassifikation:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>Profile == PXXm</code>.</li>\n<li><code>[FALSE]</code>-Zweig: Bei Nicht-PXXm-Profilen sind keine PXXm-spezifischen Zeiger erforderlich $\\rightarrow$ unmittelbarer Übergang zu <code>return [TRUE]</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Einzugrenzen auf PXXm-Pfad $\\rightarrow$ Weiterschaltung zu Schritt 2.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung des Header-Extraktionszeigers:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>extractProtocolHeaderFields == NULL</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Ungültiger Funktionszeiger $\\rightarrow$ Abbruch via <code>return [FALSE]</code>.</li>\n<li><code>[FALSE]</code>-Zweig: Zeiger vorhanden $\\rightarrow$ Weiterschaltung zu Schritt 3.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung des Transaktions-Handles:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung <code>csTransactionHandle == NULL</code>.</li>\n<li><code>[TRUE]</code>-Zweig: Fehlendes Handle $\\rightarrow$ Abbruch via <code>return [FALSE]</code>.</li>\n<li><code>[FALSE]</code>-Zweig: Beide erforderlichen Parameter sind ungleich <code>NULL</code> $\\rightarrow$ Abschluss via <code>return [TRUE]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Fehlerbehandlung & Safety-Vertrag (<code>SWS_E2EXf_00106</code>, <code>SWS_E2EXf_00180</code>):</strong></li>\n<li>Liefert <code>E2EXf_input_checks_PXXm()</code> den Wert <code>FALSE</code> zurück, bricht der Transformer die Ausführung deterministisch mit dem Fehlercode <code>E_SAFETY_HARD_RUNTIMEERROR</code> ab. Es erfolgt keine Datenverarbeitung oder PDU-Weiterleitung.</li>\n<li><strong>BSW- & Treiber-Implementierung:</strong></li>\n<li>Guard-Ausdrücke gegen Nullzeiger müssen zwingend vor jedem Speicher- oder Funktionszugriff ausgewertet werden, um Trap-/Kernel-Exceptions im BSW-Kontext zu verhindern.</li>\n<li>Spezifikations-Hinweis: Die typografischen Fehler im Diagramm (<code>extractPrtocolHeaderFields</code> sowie Guard <code>[FLASE]</code>) sind in C-Implementierungen anhand der normativen Signatur aus <code>[SWS_E2EXf_00180]</code> (<code>extractProtocolHeaderFields</code> und <code>FALSE</code>) aufzulösen.</li>\n<li><strong>RTE- & Codegenerator-Konfiguration:</strong></li>\n<li>Bei Konfiguration von Schnittstellen über Profile <code>P04m</code>, <code>P07m</code>, <code>P08m</code> oder <code>P44m</code> muss der BSW-/RTE-Generator sicherstellen, dass sowohl die Callback-Funktion zur Header-Extraktion als auch der Puffer für das Transaktions-Handle statisch instanziiert und dem Transformer übergeben werden.</li>\n<li><strong>Anforderungs-Traceability:</strong> Dient der Umsetzung von <code>RS_E2E_08538</code> zur Absicherung nachrichtenbasierter und Client/Server-Kommunikationsmuster gegen Schnittstellen-Fehlkonfigurationen.</li>\n</ul>"}], "trans": [{"from": "FIG-35ba3e0dbe6a8eaa", "to": "FIG-f709196eb7ded3ac", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Hinzufügen eines Legendenkastens („Communication Types“) mit Farbkennzeichnungen für Kommunikationsmuster (Entscheidungsknoten im Diagramm sind der Kategorie „All types“ zugeordnet).</li>\n<li>Korrektur des Tippfehlers in der Guard-Bedingung am dritten Entscheidungsknoten (<code>csTransactionHandle == NULL</code>) von <code>[FLASE]</code> zu <code>[FALSE]</code>.</li>\n<li>Bereinigung des Layouts und der Platzierung der Rückgabewerte an den beiden Aktivitätsendknoten (<code>return</code> mit Guard-Ergebnis <code>[FALSE]</code> bzw. <code>[TRUE]</code>).</li>\n</ul>"}, {"from": "FIG-f709196eb7ded3ac", "to": "FIG-72d33dd2e56f39a3", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Umbenennung des Titels des Legendenkastens von „Communication Types“ zu „Legend“.</li>\n</ul>"}]};
